assert len(phrases)==90
assert len(set(phrases))==90
for phrase in phrases:assert b.keyword_normalise(phrase) in b.keyword_normalise(text),phrase
m['keywordReview']={'sourceHash':hashlib.sha256(s.read_bytes()).hexdigest(),'phrases':phrases,'reviewed':True,'basis':'Ninety specific concepts and events present in the current English short reader.'}
p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
